import { expect, test } from '@playwright/test';

test('Log in with valid credentials', { tag: ['@smoke'] }, async ({ page }) => {
  await test.step('Open the login page', async () => {
    await page.goto('/');
  });

  await test.step('Type the email', async () => {
    await page.getByRole('textbox', { name: 'Email', exact: true }).fill('ada@example.com');
  });

  await test.step('Type the password', async () => {
    await page.getByRole('textbox', { name: 'Password', exact: true }).fill('correct-horse');
  });

  await test.step('Click Sign in', async () => {
    await page.getByRole('button', { name: 'Sign in', exact: true }).click();
  });

  await test.step('The dashboard is shown for the signed-in user', async () => {
    await expect(page.getByRole('heading', { name: 'Dashboard', exact: true, level: 1 })).toBeVisible();
    await expect(page.getByRole('paragraph').filter({ hasText: /^Signed in as Ada$/ })).toBeVisible();
  });
});
